SELECT p.gender, t.discharge_location, AVG(a.los) AS average_los, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY a.los) AS percentile_25, PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY a.los) AS percentile_50, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY a.los) AS percentile_75, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY a.los) AS percentile_90, COUNT(*) filter (WHERE a.los <= 10) AS days_less_than_10 FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN transfers t ON a.hadm_id = t.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM CURRENT_DATE) - p.birth_date >= 86 AND t.discharge_location IN ('home', 'hospice', 'in-hospital death') AND EXTRACT(YEAR FROM a.admittime) >= 2018 AND EXTRACT(YEAR FROM a.dischtime) <= 2020 AND (a.dischtime - a.admittime) <= 30 GROUP BY p.gender, t.discharge_location ORDER BY p.gender, t.discharge_location NULLS LAST;